function defaults(){return {version:'1.5.2',nickname:'Factory-Local',currentCiv:null,civLocked:false,credits:400,energy:220,steel:160,intel:0,fragments:0,dominion:0,dominionTier:1,warWins:0,buildings:{generator:1,refinery:1,lab:1,automation:1},research:[],activeDoctrine:null,contractsCompleted:0,lifetimeProduction:0,cycleProduction:0,bestIndustrialScore:0,prestigeCount:0,legacyNodes:0,civLegacies:{forge:0,bastion:0,swarm:0,nexus:0},loyalty:{forge:0,bastion:0,swarm:0,nexus:0},activeContract:null,lastTick:Date.now(),factionLocal:{forge:{pvp:0,industrial:0,operations:0},bastion:{pvp:0,industrial:0,operations:0},swarm:{pvp:0,industrial:0,operations:0},nexus:{pvp:0,industrial:0,operations:0}}};}
function loadLocal(){try{return {...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch(_){return defaults();}}
