function civPvpDescription(civ){const masteryBonus=civMastery(civ)*.5;switch(civ){case'forge':return `Mejoras económicas -${(7+masteryBonus).toFixed(1)}% costo · ataques +8% costo`;case'bastion':return `Escudos +${(14+masteryBonus).toFixed(1)}% resistencia · mejoras económicas +6% costo`;case'swarm':return `Ataques -${(12+masteryBonus).toFixed(1)}% costo · defensas +12% costo`;case'nexus':return `Sabotaje -${(26+masteryBonus).toFixed(1)}% costo · ataques +4% costo`;default:return CIVS[civ].pvp;}}
function equipDoctrine(k){if(!S.research.includes(k)||!isDoctrine(k))return;S.activeDoctrine=k;localStorage.setItem('factory-wars-v15-active-doctrine',k);saveAll();render();toast(`Doctrina equipada: ${RESEARCH[k].name}.`);}
function buyResearch(k){if(S.research.includes(k))return;const locked=researchLockReason(k);if(locked)return toast(locked,true);const c=researchCost(k);if(S.intel<c)return toast('Intel insuficiente.',true);S.intel-=c;S.research.push(k);if(isDoctrine(k)&&!S.activeDoctrine){S.activeDoctrine=k;localStorage.setItem('factory-wars-v15-active-doctrine',k);}saveAll();render();toast(`Investigación completada: ${RESEARCH[k].name}.`);}
function contractSpec(){return empireProgression.contractSpec(S);}
function contractMissing(c){return empireProgression.contractMissing(S,c);}
function startContract(){if(S.activeContract)return toast('Ya hay un contrato en curso.',true);const c=contractSpec(),missing=contractMissing(c);if(missing.some(x=>x.missing>0))return toast('Todavía faltan recursos para completar el convoy.',true);for(const {key,need} of missing)S[key]-=need;S.activeContract={...c,endsAt:Date.now()+c.seconds*1000,id:`contract_${Date.now()}`};saveAll();render();}
